CREATE TABLE `estadisticas_avanzadas_jugador` (
  `id_estadisticas` int NOT NULL AUTO_INCREMENT,
  `jugador_id` int DEFAULT NULL,
  `temporada_id` int DEFAULT NULL,
  `partidos_jugados` int DEFAULT NULL,
  `minutos_jugados` int DEFAULT NULL,
  `puntos` int DEFAULT NULL,
  `asistencias` int DEFAULT NULL,
  `rebotes_ofensivos` int DEFAULT NULL,
  `rebotes_defensivos` int DEFAULT NULL,
  `rebotes_totales` int DEFAULT NULL,
  `robos` int DEFAULT NULL,
  `tapones` int DEFAULT NULL,
  `perdidas_balon` int DEFAULT NULL,
  `faltas_cometidas` int DEFAULT NULL,
  `tiros_de_campo_intentados` int DEFAULT NULL,
  `porcentaje_tiros_de_campo` float DEFAULT NULL,
  `triples_intentados` int DEFAULT NULL,
  `porcentaje_triples` float DEFAULT NULL,
  `tiros_de_dos_intentados` int DEFAULT NULL,
  `porcentaje_tiros_de_dos` float DEFAULT NULL,
  `porcentaje_efectivo_tiros_de_campo` float DEFAULT NULL,
  `tiros_libres_intentados` int DEFAULT NULL,
  `porcentaje_tiros_libres` float DEFAULT NULL,
  `rating_ofensivo` float DEFAULT NULL,
  `rating_defensivo` float DEFAULT NULL,
  `player_efficiency_rating` float DEFAULT NULL,
  `usage_porcentage` float DEFAULT NULL,
  `win_share_ofensivo` float DEFAULT NULL,
  `win_share_defensivo` float DEFAULT NULL,
  `win_share_total` float DEFAULT NULL,
  `box_plus_minus` float DEFAULT NULL,
  PRIMARY KEY (`id_estadisticas`),
  KEY `jugador_id` (`jugador_id`),
  KEY `temporada_id` (`temporada_id`),
  CONSTRAINT `estadisticas_avanzadas_jugador_ibfk_1` FOREIGN KEY (`jugador_id`) REFERENCES `jugador` (`id_jugador`),
  CONSTRAINT `estadisticas_avanzadas_jugador_ibfk_2` FOREIGN KEY (`temporada_id`) REFERENCES `temporada` (`id_temporada`)
) ENGINE=InnoDB AUTO_INCREMENT=564 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
