  `faltas_recibidas` int DEFAULT NULL,
  `porcentaje_tiros_de_campo` float DEFAULT NULL,
  `porcentaje_triples` float DEFAULT NULL,
  `porcentaje_tiros_libres` float DEFAULT NULL,
  PRIMARY KEY (`id_jugador_partido`),
  KEY `jugador_id` (`jugador_id`),
  KEY `equipo_id` (`equipo_id`),
  KEY `enfrentamiento_id` (`enfrentamiento_id`),
  CONSTRAINT `jugador_partido_ibfk_1` FOREIGN KEY (`jugador_id`) REFERENCES `jugador` (`id_jugador`),
