  CONSTRAINT `jugador_partido_ibfk_3` FOREIGN KEY (`enfrentamiento_id`) REFERENCES `enfrentamiento` (`id_enfrentamiento`)
) ENGINE=InnoDB AUTO_INCREMENT=24088 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
